INSERT INTO `dataset` (`identifier_name`, `category`, `backend_engine`, `type`, `template`, `description`) VALUES ('current-network-throughput-trend', 'traffic_general_stat', 'qgw', 'sql', '{ "statement": "SELECT SUM( sum_in_bytes)* 8 / 15 AS avg_in_bits_per_sec, SUM( sum_out_bytes)* 8 / 15 AS avg_out_bits_per_sec, SUM( sum_in_bytes + sum_out_bytes )* 8 / 15 AS avg_bits_per_sec, SUM( sum_in_bytes )/ 15 AS avg_in_bytes_per_sec, SUM( sum_out_bytes )/ 15 AS avg_out_bytes_per_sec, SUM( sum_in_bytes + sum_out_bytes )/ 15 AS avg_bytes_per_sec, SUM( sum_in_pkts )/ 15 AS avg_in_pkts_per_sec, SUM( sum_out_pkts )/ 15 AS avg_out_pkts_per_sec, SUM( sum_in_pkts + sum_out_pkts )/ 15 AS avg_pkts_per_sec, SUM( sum_sessions )/ 15 AS avg_sessions_per_sec, SUM( max_active_sessions ) AS active_sessions FROM( SELECT device_id, vsys_id, SUM( in_bytes ) AS sum_in_bytes, SUM( out_bytes ) AS sum_out_bytes, SUM( in_pkts ) AS sum_in_pkts, SUM( out_pkts ) AS sum_out_pkts, SUM( sessions ) AS sum_sessions, max( active_sessions ) AS max_active_sessions FROM traffic_general_stat WHERE __time >= FROM_UNIXTIME( UNIX_TIMESTAMP( now())- 30 ) AND __time < FROM_UNIXTIME( UNIX_TIMESTAMP( now())- 15 ) AND vsys_id IN( ${vsys_id} ) AND ( ${filter} ) GROUP BY device_id, vsys_id )" }','System Overview-Traffic-Now. To calculate the current throughput, the metrics for each appliance are averaged over a 15-second interval. Additionally, the data ingestion latency is also set at 15 seconds.');
INSERT INTO `dataset` (`identifier_name`, `category`, `backend_engine`, `type`, `template`, `description`) VALUES ('network-throughput-trend', 'traffic_general_stat', 'qgw', 'sql', '{ "statement": "SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, AVG( sum_in_bytes)* 8 / 5 AS avg_in_bits_per_sec, AVG( sum_out_bytes )* 8 / 5 AS avg_out_bits_per_sec, AVG( sum_bytes )* 8 / 5 AS avg_bits_per_sec, AVG( sum_in_bytes )/ 5 AS avg_in_bytes_per_sec, AVG( sum_out_bytes )/ 5 AS avg_out_bytes_per_sec, AVG( sum_bytes )/ 5 AS avg_bytes_per_sec, AVG( sum_in_pkts )/ 5 AS avg_in_pkts_per_sec, AVG( sum_out_pkts )/ 5 AS avg_out_pkts_per_sec, AVG( sum_pkts )/ 5 AS avg_pkts_per_sec FROM( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') AS stat_time, SUM( in_bytes ) AS sum_in_bytes, SUM( out_bytes ) AS sum_out_bytes, SUM( in_bytes + out_bytes ) AS sum_bytes, SUM( in_pkts ) AS sum_in_pkts, SUM( out_pkts ) AS sum_out_pkts, SUM( in_pkts + out_pkts ) AS sum_pkts FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}" }','The calculation of average network throughput is capable of supporting two types of metrics, namely "bytes" and "packets".');
INSERT INTO `dataset` (`identifier_name`, `category`, `backend_engine`, `type`, `template`, `description`) VALUES ('network-throughput-packet-per-second', 'traffic_general_stat', 'qgw', 'sql', '{ "statement": "SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, AVG( sum_in_pkts)/ 5 AS avg_in_pkts_per_sec, AVG( sum_out_pkts )/ 5 AS avg_out_pkts_per_sec, AVG( sum_pkts )/ 5 AS avg_pkts_per_sec, MAX( sum_in_pkts )/ 5 AS max_in_pkts_per_sec, MAX( sum_out_pkts )/ 5 AS max_out_pkts_per_sec, MAX( sum_pkts )/ 5 AS max_pkts_per_sec, MIN( sum_in_pkts )/ 5 AS min_in_pkts_per_sec, MIN( sum_out_pkts )/ 5 AS min_out_pkts_per_sec, MIN( sum_pkts )/ 5 AS min_pkts_per_sec FROM( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') AS stat_time, SUM( in_pkts ) AS sum_in_pkts, SUM( out_pkts ) AS sum_out_pkts, SUM( in_pkts + out_pkts ) AS sum_pkts FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}" }','System Overview-Traffic-AVG, MAX, MIN. To calculate network throughput, supports metric types "bytes" and "packets," and offers aggregation methods including "average"(avg), "maximum" (max), and "minimum" (min). Based on MAX and MIN values can reveal abnormal traffic patterns, such as peak and valley outliers.');
INSERT INTO `dataset` (`identifier_name`, `category`, `backend_engine`, `type`, `template`, `description`) VALUES ('network-throughput-bit-per-second', 'traffic_general_stat', 'qgw', 'sql', '{ "statement": "SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, AVG( sum_in_bytes )* 8 / 5 AS avg_in_bits_per_sec, AVG( sum_out_bytes )* 8 / 5 AS avg_out_bits_per_sec, AVG( sum_bytes )* 8 / 5 AS avg_bits_per_sec, MAX( sum_in_bytes )* 8 / 5 AS max_in_bits_per_sec, MAX( sum_out_bytes )* 8 / 5 AS max_out_bits_per_sec, MAX( sum_bytes )* 8 / 5 AS max_bits_per_sec, MIN( sum_in_bytes )* 8 / 5 AS min_in_bits_per_sec, MIN( sum_out_bytes )* 8 / 5 AS min_out_bits_per_sec, MIN( sum_bytes )* 8 / 5 AS min_bits_per_sec FROM( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') AS stat_time, SUM( in_bytes ) AS sum_in_bytes, SUM( out_bytes ) AS sum_out_bytes, SUM( in_bytes + out_bytes ) AS sum_bytes FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( stat_time, ''${alignment_period}'', ''zero'' )) ORDER BY stat_time ASC LIMIT ${limit}" }','System Overview-Traffic-AVG, MAX, MIN. To calculate network throughput, supports metric types "bytes" and "packets," and offers aggregation methods including "average"(avg), "maximum" (max), and "minimum" (min). Based on MAX and MIN values can reveal abnormal traffic patterns, such as peak and valley outliers.');
INSERT INTO `dataset` (`identifier_name`, `category`, `backend_engine`, `type`, `template`, `description`) VALUES ('network-throughput-byte-per-second', 'traffic_general_stat', 'qgw', 'sql', '{ "statement": "SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, AVG( sum_in_bytes)/ 5 AS avg_in_bytes_per_sec, AVG( sum_out_bytes )/ 5 AS avg_out_bytes_per_sec, AVG( sum_bytes )/ 5 AS avg_bytes_per_sec, MAX( sum_in_bytes )/ 5 AS max_in_bytes_per_sec, MAX( sum_out_bytes )/ 5 AS max_out_bytes_per_sec, MAX( sum_bytes )/ 5 AS max_bytes_per_sec, MIN( sum_in_bytes )/ 5 AS min_in_bytes_per_sec, MIN( sum_out_bytes )/ 5 AS min_out_bytes_per_sec, MIN( sum_bytes )/ 5 AS min_bytes_per_sec FROM( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') AS stat_time, SUM( in_bytes ) AS sum_in_bytes, SUM( out_bytes ) AS sum_out_bytes, SUM( in_bytes + out_bytes ) AS sum_bytes FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}" }','System Overview-Traffic-AVG, MAX, MIN. To calculate network throughput, supports metric types "bytes" and "packets," and offers aggregation methods including "average"(avg), "maximum" (max), and "minimum" (min). Based on MAX and MIN values can reveal abnormal traffic patterns, such as peak and valley outliers.');
INSERT INTO `dataset` (`identifier_name`, `category`, `backend_engine`, `type`, `template`, `description`) VALUES ('new-sessions-per-second', 'traffic_general_stat', 'qgw', 'sql', '{ "statement": "SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, AVG( sum_sessions)/5 AS avg_sessions_per_sec , MAX( sum_sessions )/ 5 AS max_sessions_per_sec, MIN( sum_sessions )/ 5 AS min_sessions_per_sec FROM( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') AS stat_time, sum( sessions ) AS sum_sessions FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}" }','System Overview-New-AVG, MAX, MIN.');
INSERT INTO `dataset` (`identifier_name`, `category`, `backend_engine`, `type`, `template`, `description`) VALUES ('active-sessions', 'traffic_general_stat', 'qgw', 'sql', '{ "statement": "SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, AVG( sum_active_sessions) AS avg_active_sessions, MAX( sum_active_sessions ) AS max_active_sessions, MIN( sum_active_sessions ) AS min_active_sessions FROM( SELECT stat_time, SUM( max_active_sessions ) sum_active_sessions FROM ( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') AS stat_time, device_id, vsys_id, MAX( active_sessions ) AS max_active_sessions FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S''), device_id, vsys_id ) GROUP BY stat_time ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}" }',null);
INSERT INTO `dataset` (`identifier_name`, `category`, `backend_engine`, `type`, `template`, `description`) VALUES ('asymmetric-flows', 'traffic_general_stat', 'qgw', 'sql', '{ "statement": "SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, AVG( sum_bytes)* 8 / 5 AS avg_bits_per_sec, round( CASE WHEN sum( sum_closed_sessions ) = 0 THEN 0 ELSE SUM( sum_asymmetric_flows ) * 100.0 / SUM( sum_closed_sessions ) END, 2 ) AS percent_asymmetric_flows FROM( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') AS stat_time, SUM( in_bytes ) AS sum_in_bytes, SUM( out_bytes ) AS sum_out_bytes, SUM( in_bytes + out_bytes ) AS sum_bytes, SUM( closed_sessions ) AS sum_closed_sessions, SUM( asymmetric_c2s_flows + asymmetric_s2c_flows ) AS sum_asymmetric_flows FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id} ) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}" }',null);
INSERT INTO `dataset` (`identifier_name`, `category`, `backend_engine`, `type`, `template`, `description`) VALUES ('traffic-statistics-metrics', 'traffic_general_stat', 'qgw', 'sql', '{ "statement": "SELECT COUNT(DISTINCT(device_id)) AS device_num, SUM(sum_bytes) AS total_bytes_transferred, SUM(sum_pkts) AS total_packets_transferred, SUM(sum_sessions) AS total_new_sessions , SUM(sum_closed_sessions) AS total_closed_sessions, SUM(sum_sessions)/ ${timestampdiff_second} AS avg_new_sessions_per_second, SUM(sum_bytes)* 8 / ${timestampdiff_second} AS avg_bits_per_second, SUM(sum_pkts)/ ${timestampdiff_second} AS avg_packets_per_second, SUM(avg_active_sessions) AS avg_active_sessions, round(CASE WHEN SUM(sum_closed_sessions) = 0 THEN 0 ELSE SUM(sum_asymmetric_flows) * 100.0 / SUM(sum_closed_sessions) END, 2) AS percent_asymmetric_flows FROM( SELECT device_id, vsys_id, SUM(in_bytes + out_bytes) AS sum_bytes, SUM(in_pkts + out_pkts) AS sum_pkts, SUM(sessions) AS sum_sessions, SUM(closed_sessions) AS sum_closed_sessions, AVG(active_sessions) AS avg_active_sessions, SUM(asymmetric_c2s_flows + asymmetric_s2c_flows) AS sum_asymmetric_flows FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time <''${end}'' AND vsys_id IN ( ${vsys_id}) AND ( ${filter} ) GROUP BY device_id, vsys_id )" }','predefined dataset for the report.');
INSERT INTO `dataset` (`identifier_name`, `category`, `backend_engine`, `type`, `template`, `description`) VALUES ('traffic-summary-throughput', 'traffic_general_stat', 'qgw', 'sql', '{ "statement": "SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time , AVG(sum_in_bytes)* 8 / 5 AS avg_in_bits_per_sec, AVG(sum_out_bytes)* 8 / 5 AS avg_out_bits_per_sec, AVG(sum_bytes)* 8 / 5 AS avg_bits_per_sec FROM( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') AS stat_time, SUM(in_bytes) AS sum_in_bytes, SUM(out_bytes) AS sum_out_bytes, SUM(in_bytes + out_bytes) AS sum_bytes FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id}) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}" }','predefined dataset for the report.');
INSERT INTO `dataset` (`identifier_name`, `category`, `backend_engine`, `type`, `template`, `description`) VALUES ('traffic-summary-new-sessions-per-second', 'traffic_general_stat', 'qgw', 'sql', '{ "statement": "SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) AS stat_time, AVG(sum_sessions)/ 5 AS avg_sessions_per_sec FROM( SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'') AS stat_time, SUM(sessions) AS sum_sessions FROM traffic_general_stat WHERE __time >= ''${start}'' AND __time < ''${end}'' AND vsys_id IN ( ${vsys_id}) AND ( ${filter} ) GROUP BY TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(__time), ''PT5S'')) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL(stat_time, ''${alignment_period}'', ''zero'')) ORDER BY stat_time ASC LIMIT ${limit}" }','predefined dataset for the report.');
