INSERT INTO `dataset` (`identifier_name`, `category`, `backend_engine`, `type`, `template`, `description`) VALUES ('dos-threat-map-destination-ip-distribution', 'dos_event', 'qgw', 'sql', '{ "statement": "SELECT destination_ip, IP_TO_GEO(destination_ip) AS destination_geo, any(destination_country) AS destination_country, groupUniqArray(arrayJoin(splitByString('','', source_country_list))) AS source_coutries, MAX(bit_rate) AS max_bit_rate, MAX(packet_rate) AS max_packet_rate, MAX(session_rate) AS max_session_rate, FROM_UNIXTIME(MIN(start_time)) AS first_active_time, FROM_UNIXTIME(MAX(end_time)) AS last_active_time, MAX_DURATION(end_time, 600) AS max_duration, groupUniqArray(attack_type) AS attack_type, count(*) AS count FROM dos_event WHERE recv_time >= UNIX_TIMESTAMP(''${start}'') AND recv_time < UNIX_TIMESTAMP(''${end}'') AND vsys_id IN (${vsys_id}) AND ( ${filter} ) GROUP BY destination_ip ORDER BY count DESC LIMIT ${limit}" }',null);
INSERT INTO `dataset` (`identifier_name`, `category`, `backend_engine`, `type`, `template`, `description`) VALUES ('dos-threat-map-attack-connection', 'dos_event', 'qgw', 'sql', '{ "statement": "SELECT FROM_UNIXTIME(recv_time) AS stat_time, destination_ip, IP_TO_GEO(destination_ip) AS destination_geo, destination_country, source_country_list, attack_type, severity, bit_rate, packet_rate, session_rate FROM dos_event WHERE recv_time >= UNIX_TIMESTAMP(''${start}'') AND recv_time < UNIX_TIMESTAMP(''${end}'') AND vsys_id IN (${vsys_id}) AND ( ${filter} ) ORDER BY recv_time ASC LIMIT ${limit}" }',null);
