INSERT INTO `dataset` (`identifier_name`, `category`, `backend_engine`, `type`, `template`, `description`) VALUES ('dos-events-attack-logs', 'dos_event', 'qgw', 'sql', '{ "statement": "SELECT log_id, profile_id, vsys_id, attack_type, source_country_list, source_ip_list, destination_ip, destination_country, severity, start_time, end_time, recv_time, conditions, bit_rate, packet_rate, session_rate FROM dos_event WHERE recv_time >= UNIX_TIMESTAMP(''${start}'') AND recv_time < UNIX_TIMESTAMP(''${end}'') AND vsys_id IN (${vsys_id}) AND ( ${filter} ) ORDER BY recv_time DESC LIMIT ${limit}" }',null);
INSERT INTO `dataset` (`identifier_name`, `category`, `backend_engine`, `type`, `template`, `description`) VALUES ('dos-events-destination-ip-traffic-trend', 'dos_event', 'qgw', 'sql', '{ "statement": "SELECT FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) AS stat_time, AVG(session_rate) AS session_rate, AVG(packet_rate) AS packet_rate, AVG(bit_rate) AS bit_rate FROM traffic_top_destination_ip_metrics_log WHERE __time >= ''${start}''AND __time < ''${end}''AND vsys_id IN (${vsys_id}) AND destination_ip = ''${destination_ip}''AND attack_type = ''${attack_type}''AND ( ${filter} ) GROUP BY FROM_UNIXTIME(TIME_FLOOR_WITH_FILL( UNIX_TIMESTAMP( __time ), ''${alignment_period}'', ''zero'' )) LIMIT ${limit}" }',null);
